on conflict (parroquia, zona) do update set
  color = excluded.color, calles = excluded.calles, carga_m = excluded.carga_m,
  area_ha = excluded.area_ha, vecinos = excluded.vecinos, anillos = excluded.anillos,
  centro = excluded.centro, generado = now();

-- ── 4 · «¿A qué camión llamo por esta esquina?» ─────────────────────────────
--
-- ⛔ MANDA LA CALLE, NO EL POLÍGONO, Y ESTO SE DECIDIÓ MIDIENDO. El contorno
--    sale de una rejilla de 25 m y una casilla tiene UN solo dueño; pero dos
--    calles de zonas distintas pueden pasar por la misma casilla, así que para
--    33 de 725 tramos el polígono dice una zona y la lista dice otra. Para
--    dibujar da igual; para contestar «¿a quién llamo?» no: lo que el camión
--    recoge es la CALLE. Entonces se busca el tramo más cercano y se devuelve
--    SU zona, que es exactamente la que figura en la hoja de ese chofer.
--    El polígono queda de respaldo, para un punto sin ninguna calle cerca.
--
-- ⛔ Y se dice POR DÓNDE salió la respuesta («por»). Una respuesta de la calle
--    es exacta; una del polígono es «la manzana es de esa zona, pero ahí no
--    tenemos calle cargada». No son lo mismo y quien atiende tiene que saberlo.
create or replace function zona_en_punto(p_lat double precision, p_lon double precision,
                                         p_fecha date default current_date)
returns table (parroquia text, zona smallint, color smallint, cam text,
               por text, calle text, a_metros int)
language plpgsql stable security definer set search_path = public as $fn$
declare g record;
begin
  -- 1 · El tramo más cercano, hasta 80 m. Se mide contra cada segmento, no
  --     contra los vértices: una cuadra recta tiene 2 vértices y 100 m de largo.
  select zc.parroquia, zc.zona, zc.nombre, zc.tramo, d.m into g
    from zona_calles zc
   cross join lateral (
      select min(_dist_a_tramo_m(p_lat, p_lon,
               (zc.geom->(i-1)->>0)::double precision, (zc.geom->(i-1)->>1)::double precision,
               (zc.geom->i->>0)::double precision,     (zc.geom->i->>1)::double precision)) m
        from generate_series(1, jsonb_array_length(zc.geom) - 1) i) d
   where p_lat between zc.la_min - 0.0009 and zc.la_max + 0.0009
     and p_lon between zc.lo_min - 0.0009 and zc.lo_max + 0.0009
     and d.m <= 80
   order by d.m
   limit 1;

  if g.parroquia is not null then
    return query
    select z.parroquia, z.zona, z.color, a.cam, 'calle'::text,
           coalesce(g.nombre, 'sin nombre en el callejero')
             || coalesce(' (tramo ' || g.tramo || ')', ''),
           round(g.m)::int
      from zonas z
      left join zona_asignacion a
        on a.parroquia = z.parroquia and a.zona = z.zona
       and a.desde <= p_fecha and (a.hasta is null or a.hasta >= p_fecha)
     where z.parroquia = g.parroquia and z.zona = g.zona;
    return;
  end if;

  -- 2 · Respaldo: el contorno. ⛔ REGLA PAR-IMPAR, no «el primer anillo»: el
  --     contorno trae huecos (manzanas de adentro que le tocan al vecino). Un
  --     punto en un hueco está dentro de dos anillos: par, afuera.
  return query
  select z.parroquia, z.zona, z.color, a.cam, 'contorno'::text, null::text, null::int
    from zonas z
    left join zona_asignacion a
      on a.parroquia = z.parroquia and a.zona = z.zona
     and a.desde <= p_fecha and (a.hasta is null or a.hasta >= p_fecha)
   where (select count(*) from jsonb_array_elements(z.anillos) r
           where _punto_en_poligono(p_lat, p_lon, r.value)) % 2 = 1
   limit 1;
end $fn$;
comment on function zona_en_punto(double precision, double precision, date) is $c$De un punto del mapa: en qué zona cae y QUÉ CAMIÓN la tiene ese día. Contesta «¿a quién llamo por esta esquina?». ⛔ Manda la CALLE más cercana (hasta 80 m), no el polígono: el contorno es una rejilla de 25 m y para 33 de 725 tramos dice una zona distinta a la de la hoja del chofer. «por» dice de dónde salió: «calle» es exacto y coincide con la hoja; «contorno» es la manzana, sin calle nuestra cerca. Sin filas = fuera de las parroquias que repartimos, que NO es «no se sabe». Con una fecha vieja devuelve quién la tenía ESE día.$c$;

-- ── 5 · Lo que el mapa necesita, en una sola llamada ────────────────────────
create or replace function zonas_mapa(p_fecha date default current_date)
returns table (parroquia text, zona smallint, color smallint, anillos jsonb,
               centro jsonb, cam text, calles int, carga_m int, area_ha int, vecinos smallint[])
language sql stable security definer set search_path = public as $fn$
  select z.parroquia, z.zona, z.color, z.anillos, z.centro, a.cam,
         z.calles, z.carga_m, z.area_ha, z.vecinos
    from zonas z
    left join zona_asignacion a
      on a.parroquia = z.parroquia and a.zona = z.zona
     and a.desde <= p_fecha and (a.hasta is null or a.hasta >= p_fecha)
   order by z.parroquia, z.zona
$fn$;
comment on function zonas_mapa(date) is $c$Todas las zonas con su contorno y el camión que las tiene ese día, para pintar el mapa de una sola llamada. `cam` viene NULO mientras nadie haya asignado la zona, y el mapa lo tiene que decir — ⛔ una zona sin dueño dibujada igual que una con dueño esconde justo lo que falta hacer.$c$;

-- ── 6 · Permisos ────────────────────────────────────────────────────────────
alter table zonas            enable row level security;
alter table zona_calles      enable row level security;
alter table zona_asignacion  enable row level security;

drop policy if exists zonas_sel on zonas;
create policy zonas_sel on zonas for select to authenticated
  using (app_rol() = any (array['superadmin','admin','operador','visualizador','directivo',
                               'auditor','revisor','operativo','mecanico','rrhh']));
drop policy if exists zona_calles_sel on zona_calles;
create policy zona_calles_sel on zona_calles for select to authenticated
  using (app_rol() = any (array['superadmin','admin','operador','visualizador','directivo',
                               'auditor','revisor','operativo','mecanico','rrhh']));
drop policy if exists zona_asignacion_sel on zona_asignacion;
create policy zona_asignacion_sel on zona_asignacion for select to authenticated
  using (app_rol() = any (array['superadmin','admin','operador','visualizador','directivo',
                               'auditor','revisor','operativo','mecanico','rrhh']));
-- Escribir la asignación es decidir quién trabaja dónde: sólo quien manda.
drop policy if exists zona_asignacion_esc on zona_asignacion;
create policy zona_asignacion_esc on zona_asignacion for all to authenticated
  using (app_rol() = any (array['superadmin','admin','operador']))
  with check (app_rol() = any (array['superadmin','admin','operador']));

-- ⛔ TODA FUNCIÓN NACE ABIERTA A public/anon. [[norma-toda-funcion-nace-abierta-a-public]]
revoke all on function zona_en_punto(double precision, double precision, date) from anon, public;
revoke all on function zonas_mapa(date) from anon, public;
grant execute on function zona_en_punto(double precision, double precision, date) to authenticated;
grant execute on function zonas_mapa(date) to authenticated;

-- ── 7 · CONTROL POSITIVO ────────────────────────────────────────────────────
--
-- ⛔ SE PRUEBA LO QUE LA PIEZA TIENE QUE CONTESTAR, no una propiedad interna.
--    Lo que importa es: parado sobre una calle de la zona 5, ¿zona_en_punto
--    dice 5? Si dice otra cosa, a esa cuadra le mandan el camión equivocado.
--    El desacuerdo del CONTORNO se mide aparte y se avisa, pero no tumba la
--    migración: el contorno es para dibujar y es una rejilla de 25 m.
do $$
declare r record; malas int := 0; total int := 0; sin_zona int := 0; fuera_zona int := 0;
        poli_mal int := 0; d text := ''; resp record;
begin
  for r in
    -- ⛔ EL PUNTO DE PRUEBA VA EN MEDIO DE UNA CUADRA, NO EN UN VÉRTICE. Los
    --    vértices son ESQUINAS y una esquina la comparten dos calles: las dos
    --    quedan a distancia cero y la respuesta es un empate, no un error. Con
    --    vértices el control acusaba 26 fallas que no lo eran.
    --    [[norma-una-asercion-mal-escrita-acusa-al-producto]]
    select zc.parroquia, zc.zona, zc.nombre,
           ((zc.geom->(jsonb_array_length(zc.geom)/2)->>0)::double precision
          + (zc.geom->(jsonb_array_length(zc.geom)/2 - 1)->>0)::double precision) / 2 la,
           ((zc.geom->(jsonb_array_length(zc.geom)/2)->>1)::double precision
          + (zc.geom->(jsonb_array_length(zc.geom)/2 - 1)->>1)::double precision) / 2 lo
      from zona_calles zc
     where zc.metros >= 60 and jsonb_array_length(zc.geom) >= 2
  loop
    total := total + 1;

    -- LO QUE SE EXIGE: la respuesta de la pieza coincide con la hoja.
    select * into resp from zona_en_punto(r.la, r.lo) limit 1;
    if resp.zona is distinct from r.zona or resp.parroquia is distinct from r.parroquia then
      malas := malas + 1;
      if malas <= 5 then
        d := d || format(' [%s z%s «%s» → dijo %s z%s por %s]', r.parroquia, r.zona,
                         coalesce(r.nombre,'sin nombre'), coalesce(resp.parroquia,'NADA'),
                         coalesce(resp.zona::text,'-'), coalesce(resp.por,'-'));
      end if;
    end if;

    -- LO QUE SE AVISA: cuánto se despega el dibujo de la lista.
    perform 1 from zonas z
     where z.parroquia = r.parroquia and z.zona = r.zona
       and (select count(*) from jsonb_array_elements(z.anillos) a
             where _punto_en_poligono(r.la, r.lo, a.value)) % 2 = 1;
    if not found then poli_mal := poli_mal + 1; end if;
  end loop;

  -- Y al revés: que ninguna calle quede sin NINGUNA zona.
  -- ⛔ «FUERA DE LA ZONA DE TRABAJO» NO ES «SIN ZONA ASIGNADA», y confundirlos
  --    hace que el control acuse al reparto de abandonar 85 calles que en
  --    realidad son campo y territorio de otra empresa. En las parroquias
  --    COMPARTIDAS se reparte la zona de trabajo (poligono_zona) —lo que
  --    Betangar trabaja de verdad, medido con 48.719 posiciones—, no el
  --    límite legal: en Venancio Pulgar el límite son 71,5 km2 y la zona 11,66.
  --    [[norma-un-filtro-nuestro-tapa-un-dato-que-si-llega]]
  select count(*) into fuera_zona from calles c
    join parroquias p on p.nombre = c.parroquia
   where c.se_recolecta is not false
     and c.parroquia in ('Parroquia Venancio Pulgar')
     and c.geom is not null
     -- OJO: el alias NO puede llamarse r: en PL/pgSQL choca con la variable
     --    r record del bucle de arriba y Postgres resuelve la variable, no la
     --    tabla («record r has no field value»).
     and (select count(*) from jsonb_array_elements(p.poligono_zona) az
           where _punto_en_poligono(
             (c.geom->(jsonb_array_length(c.geom)/2)->>0)::float8,
             (c.geom->(jsonb_array_length(c.geom)/2)->>1)::float8, az.value)) % 2 = 0;

  select count(*) into sin_zona from calles c
   where c.se_recolecta is not false
     and c.parroquia in (select distinct parroquia from zonas)
     and not exists (select 1 from zona_calles zc where zc.calle_id = c.id);
  sin_zona := sin_zona - fuera_zona;

  raise notice 'CONTROL · zona_en_punto acertó en % de % tramos. Calles sin ninguna zona: % (y % fuera de la zona de trabajo, que es otra cosa).',
    total - malas, total, sin_zona, fuera_zona;
  raise notice 'AVISO · el CONTORNO (rejilla de 25 m, solo para dibujar) discrepa en % de % tramos — % por ciento.',
    poli_mal, total, round(100.0 * poli_mal / greatest(total,1), 1);

  if total = 0 then raise exception 'CONTROL MUDO: no se probó ni un tramo. Eso no es que esté bien.'; end if;
  if sin_zona > 0 then
    raise exception 'CONTROL FALLIDO: % calles de una parroquia repartida no quedaron en ninguna zona. Esas no las recoge nadie.', sin_zona;
  end if;
  if malas > 0 then
    raise exception 'CONTROL FALLIDO: zona_en_punto erró en % de % tramos.%', malas, total, d;
  end if;
end $$;
